@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h2 class="board-heading">Kanban Board</h2>

@if (isLoading)
{
    <p class="board-status">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <p class="board-error">@errorMessage</p>
}
else
{
    <BoardStatsBar Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn Status="To Do"
                     Tasks="GetFilteredTasks("To Do")"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                     OnTaskCreated="@(t => CreateTask(t, "To Do"))" />

        <BoardColumn Status="In Progress"
                     Tasks="GetFilteredTasks("In Progress")"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                     OnMoveRight="@(id => MoveTask(id, "Done"))"
                     OnTaskCreated="@(t => CreateTask(t, "In Progress"))" />

        <BoardColumn Status="Done"
                     Tasks="GetFilteredTasks("Done")"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                     OnTaskCreated="@(t => CreateTask(t, "Done"))" />
    </div>
