+    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />
+
+    <div class="board-columns">
+        <BoardColumn Status="To Do"
+                     Tasks="GetFilteredTasks("To Do")"
+                     ShowMoveLeft="false"
+                     ShowMoveRight="true"
+                     OnMoveRight="@(id => MoveTask(id, "In Progress"))"
+                     OnTaskCreated="@(t => CreateTask(t, "To Do"))" />
+
+        <BoardColumn Status="In Progress"
+                     Tasks="GetFilteredTasks("In Progress")"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="true"
+                     OnMoveLeft="@(id => MoveTask(id, "To Do"))"
+                     OnMoveRight="@(id => MoveTask(id, "Done"))"
+                     OnTaskCreated="@(t => CreateTask(t, "In Progress"))" />
+
+        <BoardColumn Status="Done"
+                     Tasks="GetFilteredTasks("Done")"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="false"
+                     OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
+                     OnTaskCreated="@(t => CreateTask(t, "Done"))" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> tasks = new();
+    private string searchText = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        var filtered = tasks.Where(t => t.Status == status);
+
+        if (!string.IsNullOrWhiteSpace(searchText))
+        {
+            filtered = filtered.Where(t =>
+                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
+        }
+
+        return filtered.ToList();
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var index = tasks.FindIndex(t => t.Id == taskId);
+            if (index >= 0)
+            {
+                var old = tasks[index];
+                tasks[index] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private async Task CreateTask(TaskItem draft, string status)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(
+                draft.Title, draft.Assignee, draft.Priority, draft.DueDate);
+            tasks.Add(created with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
+

